        _authorizeUpgrade(newImplementation);
        /// @solidity memory-safe-assembly
        assembly {
            // Clean the upper 96 bits of `newImplementation`.
            newImplementation := shr(96, shl(96, newImplementation))
            // Check if the new implementation correctly implements the `proxiableUUID` function.
            mstore(0x00, 0x5c60da1b) // `proxiableUUID()`.
            if iszero(
                and(
                    gt(returndatasize(), 0x1f),
                    staticcall(gas(), newImplementation, 0x1c, 0x04, 0x00, 0x20)
