            mstore(0x00, _UPGRADED_EVENT_SIGNATURE)
            mstore(0x20, newImplementation)
            log2(0x00, 0x40, mload(0x00), mload(0x20))
            // Update the implementation slot in storage.
            sstore(_ERC1967_IMPLEMENTATION_SLOT, newImplementation)
